"use client";

// Generated by philote from component HorseView's actions. Do not edit.
import Link from "next/link";
import { useRouter } from "next/navigation";
import { useTransition } from "react";

import { toast } from "sonner";

import { remove } from "@/lib/actions/horse-view";
import { cn } from "@/lib/utils";

import { Button, buttonVariants } from "@/components/ui/button";

export default function HorseViewActions({ id }: { id: string }) {
    const router = useRouter();
    const [pending, start] = useTransition();
    return (
        <div className="flex flex-wrap gap-2">
            <Link href={`/horses/${encodeURIComponent(id)}/edit`} className={cn(buttonVariants({ variant: "outline", size: "sm" }))}>
                {"Edit Horse"}
            </Link>
            <Button
                variant="destructive"
                size="sm"
                disabled={pending}
                onClick={() => {
                    if (!window.confirm("Delete this horse?")) {
                        return;
                    }
                    start(async () => {
                        const error = await remove(id);
                        if (error) {
                            toast.error(error);
                        } else {
                            router.refresh();
                        }
                    });
                }}
            >
                {"Delete"}
            </Button>
        </div>
    );
}
